shell_commands.command:
cd /testbed && grep -n -E 'style_components|pub style' src/config.rs && git apply <<'PATCH'
diff --git a/src/bin/bat/app.rs b/src/bin/bat/app.rs
--- a/src/bin/bat/app.rs
+++ b/src/bin/bat/app.rs
@@ -438,3 +438,48 @@ impl App {
         Ok(styled_components)
     }
 }
+
+#[test]
+fn plain_and_paging_preserve_style_and_argument_order() {
+    let cases: &[(&[&str], PagingMode)] = &[
+        (&["--plain"], PagingMode::QuitIfOneScreen),
+        (&["-pp"], PagingMode::Never),
+        (&["--paging=never", "--plain"], PagingMode::Never),
+        (&["--plain", "--paging=never"], PagingMode::Never),
+        (&["--paging=always", "--plain"], PagingMode::Always),
+        (&["--plain", "--paging=always"], PagingMode::Always),
+        (&["--paging=auto", "--plain"], PagingMode::QuitIfOneScreen),
+        (&["--plain", "--paging=auto"], PagingMode::QuitIfOneScreen),
+        (&["--paging=always", "-pp"], PagingMode::Never),
+        (&["-pp", "--paging=always"], PagingMode::Always),
+        (&["--paging=never", "-pp"], PagingMode::Never),
+        (&["-pp", "--paging=never"], PagingMode::Never),
+        (&["--paging=auto", "-pp"], PagingMode::Never),
+        (&["-pp", "--paging=auto"], PagingMode::QuitIfOneScreen),
+        (&["--plain", "--plain"], PagingMode::Never),
+        (&["--paging=always", "-p", "-p"], PagingMode::Never),
+        (&["-p", "--paging=always", "-p"], PagingMode::Never),
+        (&["-P", "-pp"], PagingMode::Never),
+        (&["-pp", "-P"], PagingMode::Never),
+        (&["-pp", "--paging=always", "-P"], PagingMode::Never),
+        (&["-pp", "-P", "--paging=always"], PagingMode::Always),
+    ];
+
+    for (args, expected_paging_mode) in cases {
+        let app = App {
+            matches: clap_app::build_app(true).get_matches_from(
+                std::iter::once("bat").chain(args.iter().copied()),
+            ),
+            interactive_output: true,
+        };
+        let config = app.config(&[]).unwrap();
+
+        assert_eq!(config.paging_mode, *expected_paging_mode, "{args:?}");
+        assert!(config.style_components.plain(), "{args:?}");
+    }
+}
diff --git a/tests/integration_tests.rs b/tests/integration_tests.rs
